//! `path.Match` and `matchHostPattern` pinned against the Go code they replaced.
//!
//! `tests/fixtures/path_match.tsv` is the 76 × 39 cross product of the patterns and names used to
//! check the port, with the Go `path.Match` verdict on each row (`ok`, `no` or `bad` for
//! `ErrBadPattern`); `tests/fixtures/host_pattern.tsv` is the same idea for `matchHostPattern`,
//! decorations (`@@`, `||`, trailing `^`) and lowercasing included. Both files were generated by
//! running the original Go functions during the migration.

use super::*;

const PATH_MATCH: &str = include_str!("../../tests/fixtures/path_match.tsv");
const HOST_PATTERN: &str = include_str!("../../tests/fixtures/host_pattern.tsv");

fn fields(line: &str) -> Vec<String> {
    line.split('\t').map(crate::fixture::unescape).collect()
}

#[test]
fn path_match_agrees_with_go() {
    let mut rows = 0;
    for line in PATH_MATCH.lines() {
        let fields = fields(line);
        assert_eq!(fields.len(), 3, "malformed fixture row: {line:?}");
        let got = match path_match(&fields[0], &fields[1]) {
            Ok(true) => "ok",
            Ok(false) => "no",
            Err(BadPattern) => "bad",
        };
        assert_eq!(
            got, fields[2],
            "pattern {:?} against {:?}",
            fields[0], fields[1]
        );
        rows += 1;
    }
    assert_eq!(rows, 2964, "the fixture is incomplete");
}

#[test]
fn host_pattern_agrees_with_go() {
    let mut rows = 0;
    for line in HOST_PATTERN.lines() {
        let fields = fields(line);
        assert_eq!(fields.len(), 3, "malformed fixture row: {line:?}");
        let expected = fields[2] == "true";
        assert_eq!(
            match_host_pattern(&fields[0], &fields[1]),
            expected,
            "pattern {:?} against host {:?}",
            fields[0],
            fields[1]
        );
        rows += 1;
    }
    assert_eq!(rows, 2765, "the fixture is incomplete");
}

#[test]
fn plain_patterns_are_host_suffixes() {
    assert!(match_host_pattern("example.com", "example.com"));
    assert!(match_host_pattern("example.com", "www.example.com"));
    assert!(match_host_pattern(".example.com", "www.example.com"));
    assert!(!match_host_pattern("example.com", "notexample.com"));
    assert!(!match_host_pattern("example.com", "example.com.evil"));
    assert!(match_host_pattern("Example.COM ", " WWW.Example.Com "));
}

#[test]
fn adguard_decorations_are_stripped() {
    assert!(match_host_pattern("@@||bank.com^", "bank.com"));
    assert!(match_host_pattern("||bank.com^", "www.bank.com"));
    assert!(match_host_pattern("@@bank.com", "bank.com"));
    assert!(!match_host_pattern("@@||bank.com^", "other.com"));
}

#[test]
fn wildcard_patterns_keep_the_star_rule() {
    // The `*.` shortcut only matches the bare suffix; `path.Match` then handles the rest.
    assert!(match_host_pattern("*.example.com", "example.com"));
    assert!(match_host_pattern("*.example.com", "www.example.com"));
    assert!(!match_host_pattern("*/example.com", "www.example.com"));
    assert!(match_host_pattern("*bank*", "mybank.com"));
}

#[test]
fn a_bad_pattern_never_matches() {
    // Go returned `err != nil` here, which `matchHostPattern` turned into "no match".
    assert!(!match_host_pattern("[", "anything"));
    assert!(!match_host_pattern("a[", "a"));
    assert!(!match_host_pattern("[-]", "-"));
    // `*` makes the chunk the rest of the pattern; the scan reports the bad class.
    assert!(!match_host_pattern("*[x-]", "x"));
}

#[test]
fn empty_input_never_matches() {
    assert!(!match_host_pattern("", "example.com"));
    assert!(!match_host_pattern("example.com", ""));
    assert!(!match_host_pattern(" ", " "));
}
